 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-5v2m0 14v2M3 12h2m14 0h2M6 6l1.4 1.4m9.2 9.2L18 18M6 18l1.4-1.4m9.2-9.2L18 6',
 robot:'M5 21h14M8 21v-4l-3-5 3-3 6 4 3-6-4-3 1-2 6 4-2 10-5 2v3M5 10l-2 2 2 3',
